"""Workspace initialization for ``ducky init``.

Creates the directory structure and ``ducky.toml``, then persists the
workspace path into the global config so lessons go where the student
expects them.
"""

from __future__ import annotations

from pathlib import Path

DUCKY_TOML_TEMPLATE = """\
# Ducky workspace config
# Generated by `ducky init`

[ducky]
# Where lesson files are stored (relative to this file, or absolute)
workspace_dir = "assignments"

# Local LLM settings (optional)
# llm_backend = "ollama"       # none | ollama | lmstudio
# ollama_model = "qwen2.5-coder:1.5b"
# ollama_url = "http://localhost:11434"

# Teacher connection (optional)
# teacher_url = "http://192.168.1.5:8420"
# teacher_token = ""
# student_name = ""
"""

README_TEMPLATE = """\
# {name}

A Ducky workspace for learning Python.

## Getting Started

1. Add lesson packs (`.duckypack` files) to the `assignments/` directory.
2. Start a lesson:
   ```
   ducky start <lesson_name>
   ```
3. Write your solution in the opened file.
4. Run tests:
   ```
   ducky test
   ```
5. Get a hint when stuck:
   ```
   ducky hint
   ```

## Directory Structure

```
assignments/          # Lesson files go here
  lesson_01_returns/  # Each lesson in its own folder
    solution.py       # Your code
    INSTRUCTIONS.md   # Assignment instructions
    quizzes/          # Teacher-authored quiz JSON before packing
    tests/            # Test files
quizzes/              # Optional shared quiz sources (`<lesson_id>.json`)
ducky.toml            # Workspace configuration
```
"""


def init_workspace(
    target_dir: str | Path,
    *,
    name: str = "",
) -> dict:
    """Initialize a Ducky workspace directory.

    Creates the directory, a ``ducky.toml`` config, and an ``assignments/``
    folder ready to receive lesson packs.

    Returns a dict with keys: ``ok``, ``path``, ``created`` (list of paths
    created), ``message``.
    """
    target = Path(target_dir).expanduser().resolve()
    created: list[str] = []

    if not target.exists():
        target.mkdir(parents=True)
        created.append(str(target))

    if not name:
        name = target.name

    # Create assignments directory
    assignments_dir = target / "assignments"
    if not assignments_dir.exists():
        assignments_dir.mkdir()
        created.append(str(assignments_dir))

    # Write ducky.toml if it doesn't exist
    toml_path = target / "ducky.toml"
    if not toml_path.exists():
        toml_path.write_text(DUCKY_TOML_TEMPLATE, encoding="utf-8")
        created.append(str(toml_path))

    # Write README.md if it doesn't exist
    readme_path = target / "README.md"
    if not readme_path.exists():
        readme_path.write_text(README_TEMPLATE.format(name=name), encoding="utf-8")
        created.append(str(readme_path))

    # Persist workspace_dir in global config so get_workspace_dir() picks it up
    from .config import save_config as _save_config

    _save_config({"workspace_dir": str(assignments_dir)})

    return {
        "ok": True,
        "path": str(target),
        "created": created,
        "message": (
            f"Ducky workspace initialized at {target}\n"
            f"  Drop .duckypack files into {assignments_dir}/\n"
            f"  Then run: cd {target} && ducky test <lesson_name>"
        ),
    }
